#include <stdio.h>

int main(void) {
    size_t n;if(scanf("%zu",&n)!=1 || n>20)return 1;
    unsigned char data[20];for(size_t i=0;i<n;++i){unsigned x;if(scanf("%u",&x)!=1 || x>255)return 1;data[i]=(unsigned char)x;}
    FILE *f=tmpfile();if(!f)return 1;
    if(fwrite(data,1,n,f)!=n || fseek(f,0,SEEK_SET)!=0){fclose(f);return 1;}
    unsigned char copy[20];if(fread(copy,1,n,f)!=n){fclose(f);return 1;}
    if(fclose(f)!=0)return 1;
    unsigned sum=0;for(size_t i=0;i<n;++i)sum+=copy[i];printf("%u\n",sum);
    return 0;
}

