#include <stdio.h>
#include <limits.h>
_Static_assert(CHAR_BIT == 8, "Нужны восьмибитные байты");
static int parse(FILE *file, unsigned *count, unsigned long *sum) {
    unsigned char header[4];
    if (fread(header,1,4,file)!=4) return 0;
    if (header[0]!=83 || header[1]!=78 || header[2]!=1 || header[3]>64) return 0;
    unsigned long total=0;
    for (unsigned i=0;i<header[3];++i) {
        unsigned char bytes[2];
        if (fread(bytes,1,2,file)!=2) return 0;
        total += (unsigned long)bytes[0] | ((unsigned long)bytes[1] << 8);
    }
    if (fgetc(file)!=EOF || ferror(file)) return 0;
    *count=header[3]; *sum=total;
    return 1;
}
int main(void) {
    unsigned n;if(scanf("%u",&n)!=1 || n>256)return 1;
    FILE *file=tmpfile();if(!file)return 1;
    int valid=1;
    for(unsigned i=0;i<n;++i){unsigned x;
        if(scanf("%u",&x)!=1 || x>255){valid=0;break;}
        unsigned char byte=(unsigned char)x;
        if(fwrite(&byte,1,1,file)!=1){valid=0;break;}
    }
    unsigned count=0;unsigned long sum=0;
    if(valid && fseek(file,0,SEEK_SET)==0)valid=parse(file,&count,&sum);else valid=0;
    if(fclose(file)!=0)valid=0;
    if(valid)printf("%u %lu\n",count,sum);else puts("ОШИБКА");
    return 0;
}
